-- Yvonne Young (profileID=25) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Yvonne Young phrasings

SELECT p.argumentID, p.phrasingID, 25, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 25
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 25 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=25 AND targArgID IN (101,103,105,107,108,109,110,111,112,113,114,115,116,118,123,130,145,148,151,153,154,155,163,169,170,171,174,175,182,184,207,217,218,219,221,222,223,230,236,238,239,240,241,278,279,280,313,317,320,321,334,335,349,350,351,352,353,355,356,357,428,476,477,484,485,500,527,539,543,544,545,546,547,551,560,561,598,603,604,606,609,640,682,683,684,685,692,693,844,863,892,893,1188,1312,1313,1314,1319,1320,1321,1345,1347,1351,1425,1498);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 25
SET pe.active = o.acceptance
WHERE pe.profileID = 25;

SELECT 'Done: endorsements for profileID=25' AS status;